mapper.select:
SELECT sc.id, sc.student_id, s.name AS student_name, s.student_no,
       sc.subject, sc.score, sc.exam_date, sc.exam_type, sc.remark,
       sc.create_time, sc.update_time, sc.is_deleted
FROM score sc
LEFT JOIN student s ON sc.student_id = s.id AND s.is_deleted = 0
WHERE s.class_id = #{classId}
  AND sc.subject = #{subject}
  AND sc.exam_date = #{examDate}
  AND sc.exam_type = #{examType}
  AND sc.is_deleted = 0
ORDER BY s.id

SELECT id, student_id, subject, score, exam_date, exam_type
FROM score
WHERE student_id = #{studentId}
  AND subject = #{subject}
  AND exam_date = #{examDate}
  AND exam_type = #{examType}
  AND is_deleted = 0
LIMIT 1

mapper.update:
UPDATE score
SET score  = #{score},
    remark = #{remark}
WHERE id = #{id}
  AND is_deleted = 0

UPDATE score
SET is_deleted = 1
WHERE id = #{id}
